  residential:[this.r.outposts.residential>=2,'恢复住宅粮食前哨'],canal:[canal,'接通水渠'],grainContract:[this.r.contractTotals.residential>=1,'完成一份住宅合同'],
  powerPlans:[this.r.tech.power&&Object.keys(this.u.plans).length>=3,'研究动力并设置三条供给计划'],solar:[this.hasBuilding('solar'),'建造太阳能板'],hordeWon:[this.s.stats.hordes>=1,'完成一次守家'],tower:[this.hasBuilding('tower')&&this.c.residents.some(r=>r.priorities.guard>0),'建造瞭望塔并安排守卫'],
