 planEstimate(id){const p=this.u.plans[id],r=this.planRecipe(id);if(!p||!r)return null;const out=Object.keys(r.out)[0],missing=Math.max(0,p.target-this.stockAmount(out)-this.pendingAmount(out)),batches=Math.ceil(missing/r.out[out]),mechanic=this.resident('mechanic'),assist=this.r.arcs.mechanic>=2&&mechanic&&mechanic.priorities.mechanic>0&&this.residentActive(mechanic),speed=1+(assist?.2:0)+(this.r.network?(this.r.arcs.mechanic>=3?.2:.1):0),lanes=this.s.buildings.filter(b=>b.type===r.station&&b.hp>0).map(()=>0);let finish=0;if(lanes.length){for(const j of this.c.production.filter(j=>j.station===r.station&&!j.ready)){const lane=lanes.indexOf(Math.min(...lanes));lanes[lane]+=j.remaining;if(j.recipe===id)finish=Math.max(finish,lanes[lane]);}finish=Math.max(finish,Math.min(...lanes))+batches*r.minutes;}return {pending:this.pendingAmount(out),minutes:Math.ceil(finish/speed),batches,speed,lanes:lanes.length};}
